/* Rebuilds public/js/brand.js (logo + watermark as base64) from public/img/*.png. Run: node scripts/build-brand.mjs */
import { readFileSync, writeFileSync } from 'node:fs';
const b64 = f => readFileSync(new URL('../public/img/' + f, import.meta.url)).toString('base64');
writeFileSync(new URL('../public/js/brand.js', import.meta.url),
  '/* Generated by scripts/build-brand.mjs from public/img. Built into the code so the logo cannot fail to load. */\n' +
  'export const LOGO_B64 = \'' + b64('siam-logo.png') + '\';\nexport const WATERMARK_B64 = \'' + b64('siam-watermark.png') + '\';\n');
